def lerp(self, a, b, t):
    e = self.node(unreal.MaterialExpressionLinearInterpolate)
    self.link(a[0], a[1], e, "A")
    self.link(b[0], b[1], e, "B")
    self.link(t[0], t[1], e, "Alpha")
    return (e, "")

