def node(self, cls, **props):
    self.n += 1
    e = MEL.create_material_expression(self.m, cls, -400 - 260 * (self.n // 10), 140 * (self.n % 10))
    for k, v in props.items():
        e.set_editor_property(k, v)
    return e

